begin;
create table public.live_session_products(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.live_sessions(id),host_id uuid not null references public.user_profiles(id),seller_id uuid not null references public.marketplace_sellers(user_id),store_id uuid not null references public.marketplace_stores(id),product_id uuid not null references public.products(id),featured_variant_id uuid references public.marketplace_product_variants(id),status text not null default'active',is_featured boolean not null default false,position integer not null,pinned_at timestamptz not null default now(),unpinned_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,constraint live_pin_status check(status in('active','removed')),constraint live_pin_state check((status='active' and unpinned_at is null and position>=0)or(status='removed' and unpinned_at is not null)),constraint live_pin_host_seller check(host_id=seller_id),constraint live_pin_version check(version>0));
create unique index live_pin_active_product on public.live_session_products(session_id,product_id)where status='active';create unique index live_pin_one_featured on public.live_session_products(session_id)where status='active'and is_featured;create index live_pin_session on public.live_session_products(session_id,position)where status='active';
create table public.marketplace_live_order_sources(id uuid primary key default gen_random_uuid(),checkout_id uuid not null references public.marketplace_checkout_sessions(id),order_id uuid not null unique references public.marketplace_orders(id),buyer_id uuid not null references auth.users(id),seller_id uuid not null references public.marketplace_sellers(user_id),store_id uuid not null references public.marketplace_stores(id),live_session_id uuid not null references public.live_sessions(id),live_host_id uuid not null references public.user_profiles(id),live_session_product_id uuid not null references public.live_session_products(id),product_id uuid not null references public.products(id),variant_id uuid not null references public.marketplace_product_variants(id),source_type text not null default'live_buy_now'check(source_type='live_buy_now'),captured_at timestamptz not null default now(),created_at timestamptz not null default now());
create or replace function public.reject_marketplace_live_source_mutation()returns trigger language plpgsql set search_path=public as $$begin raise exception using errcode='42501',message='marketplace_live_source_immutable';end$$;
create trigger marketplace_live_source_immutable before update or delete on public.marketplace_live_order_sources for each row execute function public.reject_marketplace_live_source_mutation();
create trigger live_session_products_updated_at before update on public.live_session_products for each row execute function public.marketplace_set_updated_at();
create or replace function public.live_commerce_host_context(p_session uuid)returns table(host_id uuid,store_id uuid)language plpgsql security definer set search_path=public as $$begin if auth.uid()is null then raise exception using errcode='42501',message='live_commerce_auth_required';end if;return query select l.host_id,s.id from live_sessions l join marketplace_sellers ms on ms.user_id=l.host_id and ms.status='approved'join marketplace_stores s on s.seller_id=l.host_id and s.status='active'where l.id=p_session and l.status='live'and l.host_id=auth.uid();if not found then raise exception using errcode='42501',message='live_commerce_host_not_eligible';end if;end$$;
create or replace function public.fetch_live_session_products(p_session_id uuid)returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'product_id',q.product_id,'store_id',q.store_id,'store_name',q.store_name,'seller_name',q.seller_name,'title',q.title,'description',q.description,'image_url',q.image_url,'min_price',q.min_price,'max_price',q.max_price,'compare_at_price',q.compare_at,'active_variant_count',q.variant_count,'available_quantity',q.available,'featured_variant_id',q.featured_variant_id,'is_featured',q.is_featured,'position',q.position,'availability',case when q.eligible and q.available>0 then'available'when q.eligible then'out_of_stock'else'product_unavailable'end)order by q.is_featured desc,q.position),'[]'::jsonb)from(select lp.*,st.name store_name,coalesce(up.display_name,up.username) seller_name,p.title,p.description,case when p.images[1]~'^https://'then p.images[1]end image_url,min(v.price)filter(where v.status='active')min_price,max(v.price)filter(where v.status='active')max_price,max(v.compare_at_price)filter(where v.status='active')compare_at,count(v.id)filter(where v.status='active')variant_count,coalesce(sum(greatest(i.on_hand-i.reserved,0))filter(where v.status='active'),0)available,(p.status='active'and p.moderation_status='approved'and p.deleted_at is null and p.product_type='physical'and p.currency='BDAG'and st.status='active'and ms.status='approved')eligible from live_session_products lp join live_sessions l on l.id=lp.session_id and l.status='live'join products p on p.id=lp.product_id join marketplace_stores st on st.id=lp.store_id join marketplace_sellers ms on ms.user_id=lp.seller_id join user_profiles up on up.id=lp.seller_id left join marketplace_product_variants v on v.product_id=p.id and v.archived_at is null left join marketplace_inventory_levels i on i.variant_id=v.id where lp.session_id=p_session_id and lp.status='active'group by lp.id,st.id,up.id,p.id,ms.user_id)q$$;
create or replace function public.fetch_my_live_product_candidates(p_session_id uuid,p_limit integer default 20,p_before_updated_at timestamptz default null,p_before_id uuid default null)returns jsonb language plpgsql stable security definer set search_path=public as $$declare c record;n integer:=least(greatest(coalesce(p_limit,20),1),50);begin if(p_before_updated_at is null)<>(p_before_id is null)then raise exception using message='live_commerce_invalid_cursor';end if;select*into c from live_commerce_host_context(p_session_id);return(select coalesce(jsonb_agg(jsonb_build_object('product_id',q.id,'store_id',q.store_id,'store_name',q.store_name,'title',q.title,'image_url',q.image_url,'min_price',q.min_price,'max_price',q.max_price,'active_variant_count',q.variant_count,'available_quantity',q.available,'pin_id',q.pin_id,'is_pinned',q.pin_id is not null,'is_featured',coalesce(q.is_featured,false),'updated_at',q.updated_at)order by q.updated_at desc,q.id desc),'[]'::jsonb)from(select p.id,p.store_id,s.name store_name,p.title,case when p.images[1]~'^https://'then p.images[1]end image_url,p.updated_at,min(v.price)min_price,max(v.price)max_price,count(v.id)variant_count,coalesce(sum(greatest(i.on_hand-i.reserved,0)),0)available,max(lp.id)pin_id,bool_or(coalesce(lp.is_featured,false))is_featured from products p join marketplace_stores s on s.id=p.store_id left join marketplace_product_variants v on v.product_id=p.id and v.status='active'and v.archived_at is null left join marketplace_inventory_levels i on i.variant_id=v.id left join live_session_products lp on lp.session_id=p_session_id and lp.product_id=p.id and lp.status='active'where p.seller_id=c.host_id and p.store_id=c.store_id and p.status='active'and p.moderation_status='approved'and p.deleted_at is null and p.product_type='physical'and p.currency='BDAG'and(p_before_updated_at is null or(p.updated_at,p.id)<(p_before_updated_at,p_before_id))group by p.id,s.id order by p.updated_at desc,p.id desc limit n)q);end$$;
create or replace function public.pin_live_session_product(p_session_id uuid,p_product_id uuid,p_featured_variant_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare c record;p products;v marketplace_product_variants;r live_session_products;begin if p_idempotency_key is null then raise exception using message='live_commerce_invalid_input';end if;select*into c from live_commerce_host_context(p_session_id);perform pg_advisory_xact_lock(hashtextextended('live-pin:'||p_session_id,0));select*into p from products where id=p_product_id and seller_id=c.host_id and store_id=c.store_id;if not found or p.status<>'active'or p.moderation_status<>'approved'or p.product_type<>'physical'or p.currency<>'BDAG'or p.deleted_at is not null then raise exception using message='live_commerce_product_unavailable';end if;if p_featured_variant_id is not null then select*into v from marketplace_product_variants where id=p_featured_variant_id and product_id=p.id and status='active'and archived_at is null;if not found then raise exception using message='live_commerce_invalid_variant';end if;end if;if not exists(select 1 from marketplace_product_variants x join marketplace_inventory_levels i on i.variant_id=x.id where x.product_id=p.id and x.status='active'and i.on_hand>i.reserved)then raise exception using message='live_commerce_out_of_stock';end if;select*into r from live_session_products where session_id=p_session_id and product_id=p.id and status='active';if found then return jsonb_build_object('id',r.id,'idempotent',true);end if;if(select count(*)from live_session_products where session_id=p_session_id and status='active')>=20 then raise exception using message='live_commerce_pin_limit';end if;if p_featured_variant_id is not null then update live_session_products set is_featured=false,version=version+1 where session_id=p_session_id and status='active'and is_featured;end if;insert into live_session_products(session_id,host_id,seller_id,store_id,product_id,featured_variant_id,is_featured,position)values(p_session_id,c.host_id,c.host_id,c.store_id,p.id,p_featured_variant_id,p_featured_variant_id is not null,(select count(*)from live_session_products where session_id=p_session_id and status='active'))returning*into r;return jsonb_build_object('id',r.id,'idempotent',false);end$$;
create or replace function public.unpin_live_session_product(p_session_id uuid,p_live_session_product_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare c record;r live_session_products;begin if p_idempotency_key is null then raise exception using message='live_commerce_invalid_input';end if;select*into c from live_commerce_host_context(p_session_id);select*into r from live_session_products where id=p_live_session_product_id and session_id=p_session_id for update;if not found then raise exception using message='live_commerce_pin_not_found';end if;if r.status='removed'then return jsonb_build_object('id',r.id,'status',r.status);end if;update live_session_products set status='removed',is_featured=false,unpinned_at=now(),version=version+1 where id=r.id;return jsonb_build_object('id',r.id,'status','removed');end$$;
create or replace function public.feature_live_session_product(p_session_id uuid,p_live_session_product_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare c record;begin if p_idempotency_key is null then raise exception using message='live_commerce_invalid_input';end if;select*into c from live_commerce_host_context(p_session_id);perform pg_advisory_xact_lock(hashtextextended('live-feature:'||p_session_id,0));if not exists(select 1 from live_session_products where id=p_live_session_product_id and session_id=p_session_id and status='active')then raise exception using message='live_commerce_pin_not_found';end if;update live_session_products set is_featured=(id=p_live_session_product_id),version=version+1 where session_id=p_session_id and status='active'and is_featured is distinct from(id=p_live_session_product_id);return fetch_live_session_products(p_session_id);end$$;
create or replace function public.create_live_marketplace_checkout_reservation(p_session_id uuid,p_live_session_product_id uuid,p_variant_id uuid,p_quantity integer,p_shipping_address jsonb,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare l live_sessions;pin live_session_products;v marketplace_product_variants;result jsonb;checkout uuid;ord uuid;begin select*into l from live_sessions where id=p_session_id for share;if not found or l.status<>'live'then raise exception using message='live_commerce_live_ended';end if;select*into pin from live_session_products where id=p_live_session_product_id and session_id=l.id and status='active'for share;if not found then raise exception using message='live_commerce_pin_unavailable';end if;select*into v from marketplace_product_variants where id=p_variant_id and product_id=pin.product_id and status='active'and archived_at is null;if not found then raise exception using message='live_commerce_invalid_variant';end if;if auth.uid()=pin.seller_id then raise exception using message='marketplace_own_product_forbidden';end if;result:=create_marketplace_checkout_reservation(jsonb_build_array(jsonb_build_object('variant_id',p_variant_id,'quantity',p_quantity)),p_shipping_address,p_idempotency_key);checkout:=(result->'checkout'->>'id')::uuid;select id into ord from marketplace_orders where checkout_id=checkout;insert into marketplace_live_order_sources(checkout_id,order_id,buyer_id,seller_id,store_id,live_session_id,live_host_id,live_session_product_id,product_id,variant_id)values(checkout,ord,auth.uid(),pin.seller_id,pin.store_id,l.id,l.host_id,pin.id,pin.product_id,v.id)on conflict(order_id)do nothing;if not exists(select 1 from marketplace_live_order_sources where order_id=ord and live_session_id=l.id and live_session_product_id=pin.id and variant_id=v.id)then raise exception using message='marketplace_idempotency_conflict';end if;return result;end$$;
alter table live_session_products enable row level security;alter table marketplace_live_order_sources enable row level security;create policy live_pin_realtime_read on live_session_products for select using(exists(select 1 from live_sessions l where l.id=session_id and l.status='live'));revoke all on live_session_products from public,anon,authenticated;grant select on live_session_products to anon,authenticated;revoke all on marketplace_live_order_sources from public,anon,authenticated;revoke all on function live_commerce_host_context(uuid),fetch_my_live_product_candidates(uuid,integer,timestamptz,uuid),pin_live_session_product(uuid,uuid,uuid,uuid),unpin_live_session_product(uuid,uuid,uuid),feature_live_session_product(uuid,uuid,uuid),create_live_marketplace_checkout_reservation(uuid,uuid,uuid,integer,jsonb,uuid)from public,anon;grant execute on function fetch_live_session_products(uuid)to anon,authenticated,service_role;grant execute on function fetch_my_live_product_candidates(uuid,integer,timestamptz,uuid),pin_live_session_product(uuid,uuid,uuid,uuid),unpin_live_session_product(uuid,uuid,uuid),feature_live_session_product(uuid,uuid,uuid),create_live_marketplace_checkout_reservation(uuid,uuid,uuid,integer,jsonb,uuid)to authenticated,service_role;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime'and schemaname='public'and tablename='live_session_products')then alter publication supabase_realtime add table live_session_products;end if;end$$;
commit;
